command:example.dev:code:
$chart = New-ImageTopology -TopologyDefinition {
                New-ImageTopologyNode -Id api -Label API -Kind Service
                New-ImageTopologyNode -Id db -Label Database -Kind Database
                New-ImageTopologyEdge -SourceNodeId api -TargetNodeId db -Kind Dependency
            } -Layout Layered -FilePath service-map.svg -PassThru
            $chart | Get-ImageTopologyDiagnostics -LayoutPreset Balanced

New-ImageChart -ChartsDefinition {
                New-ImageChartBar -Name 'Q1' -Value 12,18,25 -Color CornflowerBlue
                New-ImageChartBar -Name 'Q2' -Value 14,20,28 -Color Orange
            } -FilePath chart.png -XTitle 'Month' -YTitle 'Revenue'

$builds = Import-Csv builds.csv   # Day, Passed, Failed
            New-ImageChart -Title 'Builds by result' -Subtitle 'Week 41' -XLabel $builds.Day -FilePath builds.png -Options (New-ImageChartOptions -BarLayout Stacked -ShowLegend) {
                New-ImageChartBar -Name Passed -Value $builds.Passed
                New-ImageChartBar -Name Failed -Value $builds.Failed
            }

New-ImageChart -XLabel Mon, Tue, Wed, Thu, Fri -FilePath latency.webp {
                New-ImageChartBar -Name Requests -Value 410, 380, 455, 520, 470
                New-ImageChartLine -Name 'p95 (ms)' -Value 182, 175, 240, 310, 205 -Marker Circle -SecondaryAxis
            } -SecondaryYTitle 'p95 (ms)'

New-ImageChart -Title 'Builds' -XLabel Mon, Tue, Wed -FilePath builds.png {
                New-ImageChartBar -Name Passed -Value 41, 38, 45
                New-ImageChartLine -Name Target -Value 40, 40, 40 -Color '#c78404'
            }

New-ImageChart -XLabel Mon, Tue, Wed, Thu -SecondaryYTitle 'Error rate (%)' -FilePath combo.png {
                New-ImageChartBar -Name Requests -Value 410, 380, 455, 520
                New-ImageChartLine -Name 'Error rate' -Value 1.2, 0.8, 2.4, 1.1 -Marker Diamond -MarkerSize 8 -SecondaryAxis
            }

$story = New-ImageConsoleStory -Dialect CSharp -Title 'dotnet run - ChartForgeX' -Content {
               New-ImageConsoleStoryCommand -Text 'var chart = Chart.Create().WithTitle("Weekly builds");'
               New-ImageConsoleStoryCommand -Text 'chart.SavePng("weekly-builds.png");'
               New-ImageConsoleStoryOutput -Text 'Saved weekly-builds.png' -Style Success
             }
             $story | Export-ImageConsoleStory -Path '.\chart-demo.gif' -FramesPerSecond 10 -EndHoldSeconds 1.5

$story = New-ImageConsoleStory -Speed Normal -TypingSpeed 36 -TabHoldSeconds 2.5 -Content {
               New-ImageConsoleStoryCommand -Text 'Invoke-ProjectBuild'
               New-ImageConsoleStoryOutput -Text 'Build completed.' -Style Success
             }

$events = @(
                @{ TimestampSeconds = 1; Kind = 'Command'; Text = './Test-Project.ps1' }
                @{ TimestampSeconds = 12; Kind = 'Output'; Text = '24 checks passed'; Tone = 'Success' }
            )
            $replay = New-ImageStoryReplay -DurationSeconds 15 -Events $events
            $replay.CompressPauses([TimeSpan]::FromSeconds(2))

$services | New-ImageTableBlock -Title Services -StatusColumn Status -Width 616 -Height 270 -Property Name, Status,
                @{ Name = 'Requests'; Expression = { [int] $_.Requests }; FormatString = 'N0'; Alignment = 'Right' },
                @{ Name = 'P95'; Expression = { "$($_.P95) ms" }; Alignment = 'Right' }

New-ImageTopology -TopologyDefinition {
                New-ImageTopologyNode -Id api -Label API -Kind Service -Status Healthy -Symbol API
                New-ImageTopologyNode -Id db -Label Database -Kind Database -Status Warning -Symbol SQL
                New-ImageTopologyEdge -SourceNodeId api -TargetNodeId db -Label '32 ms' -Kind Dependency -Status Warning -Direction Forward
            } -Title 'Service map' -Layout Layered -Direction LeftToRight -FilePath service-map.png

New-ImageVisualStory -StoryScript {
              param($Story)
              [void] $Story.WithTitle('Engineering signal').WithColumns(1)
              $metric = [ChartForgeX.VisualBlocks.MetricCard]::Create().WithMetric('Projects', '126')
              [void] $Story.Add('projects', $metric)
            } -MotionDefinition {
              New-ImageVisualMotionCue -TargetId title -Effect Reveal -DurationSeconds 0.9
              New-ImageVisualMotionCue -TargetId projects -Effect Rise -DelaySeconds 0.3
            } -FilePath profile.svg

$motion = [ChartForgeX.Motion.VisualMotionTimeline]::Create().Rise('requests')
            New-ImageVisualGrid -ContentDefinition {
              New-ImageVisualGridItem -TargetId requests -Block (New-ImageMetricCard -Label Requests -Value 12840)
            } -Motion $motion | New-ImageVisualStory -FilePath requests.svg
